query:
SELECT id, title, article_type, status, quality_score, public_path, optimization_task_id FROM geo_articles WHERE project_id = 1 ORDER BY id LIMIT 10;
SELECT id, article_id, optimization_task_id, quality_score, publish_url, publish_status, need_retest, publish_channel FROM geo_publish_records WHERE project_id = 1 ORDER BY id DESC LIMIT 5;
SELECT id, task_name, status, need_retest, published_url FROM optimization_tasks WHERE project_id = 1 AND id IN (120010, 120011, 120012) ORDER BY id;
SELECT (SELECT COUNT(*) FROM geo_reports WHERE project_id = 1) AS report_count, (SELECT COUNT(*) FROM content_templates WHERE project_id = 1) AS template_count, (SELECT COUNT(*) FROM ai_response_analyses WHERE project_id = 1 AND manually_reviewed = 1) AS manually_reviewed_analysis_count, (SELECT COUNT(*) FROM customer_questions WHERE project_id = 1 AND source = 'manual') AS specified_question_count;

